const uint32_t DEFAULT_BLOCK_DIM = 8;
static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    ConvTransposed2dSquareInputAsymmetricKernelCustomTiling tiling;

    // 输入 x: [N, Cin, H, W]
    const gert::Shape* x_shape = context->GetInputShape(0);
    // 权重 w: [Cin, Cout, Kh, Kw] (与 PyTorch ConvTranspose2d 权重布局一致)
    const gert::Shape* w_shape = context->GetInputShape(1);

    if (x_shape->GetDimNum() != 4 || w_shape->GetDimNum() != 4) {
        return ge::GRAPH_FAILED;
    }

    uint32_t N  = static_cast<uint32_t>(x_shape->GetDim(0));
    uint32_t Cin = static_cast<uint32_t>(x_shape->GetDim(1));
    uint32_t H  = static_cast<uint32_t>(x_shape->GetDim(2));
    uint32_t W  = static_cast<uint32_t>(x_shape->GetDim(3));

    uint32_t Cin_w = static_cast<uint32_t>(w_shape->GetDim(0));
    uint32_t Cout  = static_cast<uint32_t>(w_shape->GetDim(1));
    uint32_t Kh    = static_cast<uint32_t>(w_shape->GetDim(2));
    uint32_t Kw    = static_cast<uint32_t>(w_shape->GetDim(3));

    // 简单校验
    if (Cin != Cin_w) {
        return ge::GRAPH_FAILED;
    }

    // 设置 block 数
    context->SetBlockDim(DEFAULT_BLOCK_DIM);

    // 计算输出形状 (stride=1, padding=0, output_padding=0 场景)
    uint32_t Hout = H + Kh - 1;
    uint32_t Wout = W + Kw - 1;

    // 将 tiling 参数写入
    tiling.set_n(N);
    tiling.set_cin(Cin);
    tiling.set_cout(Cout);
    tiling.set_h(H);
    tiling.set_w(W);
    tiling.set_kh(Kh);
    tiling.set_kw(Kw);
    // 行分片高度，简化为固定值
    uint32_t tileH = (H > 32) ? 32 : H;
    tiling.set_tileH(tileH);
    tiling.set_blockDim(DEFAULT_BLOCK_DIM);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    // workspace
    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;

    return ge::GRAPH_SUCCESS;
}
}

